CREATE TABLE "requests"."request_obd_codes"
(
    "id"         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "request_id" bigint       NOT NULL,
    "obd_code"   varchar(255) NOT NULL
);

COMMENT
ON TABLE "requests"."request_obd_codes" IS 'This table will hold the OBD codes related to the request.'
COMMENT
ON COLUMN "requests"."request_obd_codes"."request_id" IS 'Allows multiple OBD codes per request';
COMMENT
ON COLUMN "requests"."request_obd_codes"."obd_code" IS 'e.g., P0420, P0301';

CREATE INDEX ON "requests"."request_obd_codes" ("request_id");